using System.Text.Json;
using System.Text.RegularExpressions;

namespace DotCharter.Tests.Infrastructure;

/// <summary>
///     Dependency licence compliance (#828). <c>licenses/dependencies.json</c> is the
///     committed inventory: every NuGet package the solution resolves (generated by
///     <c>tools/release/Update-DependencyInventory.ps1</c>) and every vendored native
///     component, tool, font and asset (curated). These rules read the inventory and
///     the <c>obj/project.assets.json</c> the build wrote, never the network:
///     a new package must be in the inventory, and every bundled licence must be on
///     the GPL-3.0-compatible allowlist, or the gate fails and says what to do.
/// </summary>
public sealed partial class DependencyLicenceTests
{
    /// <summary>SPDX ids that may be combined into a GPL-3.0-or-later program.</summary>
    private static readonly HashSet<string> CodeAllowlist = new(StringComparer.OrdinalIgnoreCase)
    {
        "MIT", "MIT-0", "BSD-2-Clause", "BSD-3-Clause", "0BSD", "Apache-2.0", "ISC", "Zlib", "MS-PL", "BSL-1.0",
        "LGPL-2.0-only", "LGPL-2.0-or-later", "LGPL-2.1-only", "LGPL-2.1-or-later", "LGPL-3.0-only", "LGPL-3.0-or-later",
        "GPL-2.0-or-later", "GPL-3.0-only", "GPL-3.0-or-later", "AGPL-3.0-only", "AGPL-3.0-or-later",
        "MPL-2.0", "OFL-1.1", "Unlicense", "CC0-1.0", "LicenseRef-Public-Domain"
    };

    /// <summary>Extra ids accepted for DATA (recordings, captures), never for code.</summary>
    private static readonly HashSet<string> DataAllowlist = new(StringComparer.OrdinalIgnoreCase) { "CC-BY-4.0" };

    /// <summary>
    ///     Licences reviewed by hand and accepted although they are not on the list,
    ///     each with the reason. Adding one here is a legal decision: write the reason.
    /// </summary>
    private static readonly Dictionary<string, string> ReviewedExceptions = new(StringComparer.OrdinalIgnoreCase)
    {
        ["LicenseRef-Microsoft-DirectML-Redistributable"] =
            "DirectML.dll is a Microsoft redistributable, shipped unmodified beside the app and covered by DotCharter's GPL-3.0 section 7 additional permission for DirectML (THIRD-PARTY-NOTICES.md section 1); its licence permits redistribution (THIRD-PARTY-NOTICES.md 2.3)."
    };

    private static readonly string[] SkippedDirectories =
        [".git", ".claude", ".codex", ".agents", "bin", "node_modules", "TestData", "artifacts", "_deps", "build"];

    private static JsonElement Inventory() =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(TestPaths.RepoRoot(), "licenses", "dependencies.json"))).RootElement;

    private static List<(string Id, string Version, string License)> InventoryPackages() =>
        Inventory().GetProperty("packages").EnumerateArray()
            .Select(p => (p.GetProperty("id").GetString()!, p.GetProperty("version").GetString()!, p.GetProperty("license").GetString()!))
            .ToList();

    private static List<JsonElement> NativeEntries() => Inventory().GetProperty("native").EnumerateArray().ToList();

    private static IEnumerable<string> AssetsFiles(string dir, int depth)
    {
        var assets = Path.Combine(dir, "obj", "project.assets.json");
        if (File.Exists(assets)) yield return assets;
        if (depth == 0) yield break;
        foreach (var sub in Directory.EnumerateDirectories(dir))
        {
            if (SkippedDirectories.Contains(Path.GetFileName(sub), StringComparer.OrdinalIgnoreCase)) continue;
            foreach (var file in AssetsFiles(sub, depth - 1)) yield return file;
        }
    }

    /// <summary>Every package id/version the repository's projects resolved, and the directly referenced ids.</summary>
    private static (SortedSet<string> All, SortedSet<string> Direct) ResolvedPackages()
    {
        var all = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
        var direct = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var file in AssetsFiles(TestPaths.RepoRoot(), 5))
        {
            using var doc = JsonDocument.Parse(File.ReadAllText(file));
            foreach (var lib in doc.RootElement.GetProperty("libraries").EnumerateObject())
            {
                if (lib.Value.GetProperty("type").GetString() == "package") all.Add(lib.Name);
            }

            foreach (var group in doc.RootElement.GetProperty("projectFileDependencyGroups").EnumerateObject())
            {
                foreach (var dep in group.Value.EnumerateArray())
                    direct.Add(dep.GetString()!.Split(' ')[0]);
            }
        }

        return (all, direct);
    }

    [Fact]
    public void The_inventory_names_every_package_the_build_resolved()
    {
        var (resolved, _) = ResolvedPackages();
        Assert.True(resolved.Count > 50, $"Found only {resolved.Count} resolved packages: build the solution so obj/project.assets.json exists.");

        var inventory = InventoryPackages().Select(p => $"{p.Id}/{p.Version}").ToHashSet(StringComparer.OrdinalIgnoreCase);
        var missing = resolved.Where(r => !inventory.Contains(r)).ToList();
        Assert.True(missing.Count == 0,
            "These packages are referenced but not in licenses/dependencies.json: " + string.Join(", ", missing) +
            ". Run tools/release/Update-DependencyInventory.ps1 (it stops on a licence it cannot read), check each licence is GPL-3.0-compatible, and commit the file.");
    }

    [Fact]
    public void Every_bundled_dependency_has_a_licence_on_the_allowlist()
    {
        var bad = new List<string>();
        foreach (var (id, version, license) in InventoryPackages())
        {
            if (!Compatible(license, false)) bad.Add($"package {id} {version}: {license}");
        }

        foreach (var entry in NativeEntries())
        {
            var distribution = entry.GetProperty("distribution").GetString();
            if (distribution != "bundled") continue;
            var license = entry.GetProperty("license").GetString()!;
            if (!Compatible(license, entry.GetProperty("category").GetString() is "asset" or "model")) bad.Add($"{entry.GetProperty("name").GetString()}: {license}");
        }

        Assert.True(bad.Count == 0,
            "Not GPL-3.0-compatible (or unknown) licence: " + string.Join("; ", bad) +
            ". Do not ship it: replace the dependency. If the licence is actually fine, add its SPDX id to the allowlist in DependencyLicenceTests, or a ReviewedExceptions entry with the reason; if it is a recording or other data, the category must be \"asset\".");
    }

    [Fact]
    public void Dependencies_that_are_not_bundled_say_why_in_a_note()
    {
        var silent = NativeEntries()
            .Where(e => e.GetProperty("distribution").GetString() != "bundled" && !e.TryGetProperty("note", out _))
            .Select(e => e.GetProperty("name").GetString())
            .ToList();
        Assert.True(silent.Count == 0, "Entries that are not bundled need a `note` saying how they are kept out or fetched: " + string.Join(", ", silent));
    }

    [Fact]
    public void The_notices_name_every_directly_referenced_package_and_every_native_entry()
    {
        var notices = File.ReadAllText(Path.Combine(TestPaths.RepoRoot(), "THIRD-PARTY-NOTICES.md"));
        var (_, direct) = ResolvedPackages();
        var packageIds = InventoryPackages().Select(p => p.Id).ToHashSet(StringComparer.OrdinalIgnoreCase);
        var missing = direct.Where(id => packageIds.Contains(id)).Where(id => !notices.Contains($"`{id}`", StringComparison.Ordinal)).ToList();
        missing.AddRange(NativeEntries()
            .Select(e => e.GetProperty("notice").GetString()!)
            .Where(n => !notices.Contains(n, StringComparison.Ordinal))
            .Select(n => $"native '{n}'"));
        Assert.True(missing.Count == 0,
            "THIRD-PARTY-NOTICES.md does not name: " + string.Join(", ", missing) + ". Add them to section 2.3 (packages) or 2.2/2.4/2.5 (native), with the licence.");
    }

    [Fact]
    public void The_allowlist_rejects_an_incompatible_or_unknown_licence()
    {
        // The rule itself, so the lint above cannot pass by accepting everything.
        Assert.False(Compatible("SSPL-1.0", false));
        Assert.False(Compatible("LicenseRef-Proprietary", false));
        Assert.False(Compatible("CC-BY-NC-4.0", true));
        Assert.False(Compatible("MIT AND SSPL-1.0", false));
        Assert.False(Compatible("CC-BY-4.0", false));
        Assert.True(Compatible("CC-BY-4.0", true));
        Assert.True(Compatible("MIT OR SSPL-1.0", false));
        Assert.True(Compatible("(MIT OR Apache-2.0) AND BSD-3-Clause", false));
        Assert.True(Compatible("GPL-2.0-or-later WITH Classpath-exception-2.0", false));
        Assert.True(Compatible("Apache-2.0+", false));
    }

    /// <summary>An SPDX expression is compatible when OR has a compatible side and every AND side is.</summary>
    private static bool Compatible(string expression, bool data) => new ExpressionParser(Tokenize(expression), data).Parse();

    private static List<string> Tokenize(string expression) =>
        TokenPattern().Matches(expression).Select(m => m.Value).ToList();

    [GeneratedRegex(@"\(|\)|[^\s()]+")]
    private static partial Regex TokenPattern();

    private sealed class ExpressionParser(List<string> tokens, bool data)
    {
        private int _position;

        public bool Parse() => Or();

        private bool Or()
        {
            var result = And();
            while (Peek() == "OR")
            {
                _position++;
                var right = And();
                result = result || right;
            }

            return result;
        }

        private bool And()
        {
            var result = Term();
            while (Peek() == "AND")
            {
                _position++;
                var right = Term();
                result = result && right;
            }

            return result;
        }

        private bool Term()
        {
            var token = tokens.Count > _position ? tokens[_position++] : "";
            if (token == "(")
            {
                var inner = Or();
                if (Peek() == ")") _position++;
                return inner;
            }

            if (Peek() == "WITH") _position += 2;
            var id = token.TrimEnd('+');
            return CodeAllowlist.Contains(id) || (data && DataAllowlist.Contains(id)) || ReviewedExceptions.ContainsKey(id);
        }

        private string? Peek() => _position < tokens.Count ? tokens[_position] : null;
    }
}
